package com.example.examplemod.cargo.center;

import net.minecraft.nbt.*;
import java.util.*;

/** Real production ledger calls: cash conservation, actual receipts, debt, tariff freeze and return reserve. */
public final class RailEconomyCheck {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static final class Accounts implements CargoCommerceBook.Accounts {
        final Map<OwnerRef,Long> balances=new HashMap<>();
        final Set<OwnerRef> blocked=new HashSet<>();
        public long balance(OwnerRef o){return balances.getOrDefault(o,0L);}public boolean debit(OwnerRef o,long n){if(n<0||balance(o)<n)return false;balances.put(o,balance(o)-n);return true;}public boolean canCredit(OwnerRef o,long n){return !blocked.contains(o)&&n>=0&&balance(o)<=Long.MAX_VALUE-n;}public void credit(OwnerRef o,long n){balances.put(o,Math.addExact(balance(o),n));}public long maximum(){return 1_000_000;}public void dirty(){}
    }
    public static void main(String[] args){
        var payer=OwnerRef.player(UUID.randomUUID());var roadOwner=OwnerRef.player(UUID.randomUUID());var accounts=new Accounts();var book=new RailTollBook(accounts);UUID road=UUID.randomUUID();
        book.register(road,roadOwner,"Rail",100,List.of(new RailGeometry.Span("line",0,10),new RailGeometry.Span("line",10,100)));
        require(book.road(road).orElseThrow().spans().size()==1,"adjacent claim intervals normalized; one actual distance cannot be billed twice");
        boolean overlap=false;try{book.register(UUID.randomUUID(),payer,"Overlap",1,List.of(new RailGeometry.Span("line",20,40)));}catch(IllegalArgumentException expected){overlap=true;}require(overlap&&book.roads().size()==1,"overlapping claim rejected atomically");
        UUID receipt=UUID.randomUUID();book.travel(receipt,payer,book.charges(new RailGeometry.Span("line",0,10)));require(book.totalDebt(payer)==1&&accounts.balance(roadOwner)==0,"unfunded travel creates debt and never money");book.travel(receipt,payer,book.charges(new RailGeometry.Span("line",0,10)));require(book.totalDebt(payer)==1,"same movement receipt not assessed twice");
        accounts.balances.put(payer,1L);var debt=book.debts().getFirst();UUID repayment=UUID.randomUUID();require(book.repay(debt.id(),1,repayment)==1&&book.totalDebt(payer)==0&&accounts.balance(roadOwner)==1,"repayment transfers actual existing CR");require(book.repay(debt.id(),1,repayment)==0&&accounts.balance(roadOwner)==1,"repayment nonce is idempotent");
        book.travel(UUID.randomUUID(),payer,List.of(new RailTollBook.Charge(road,roadOwner,1,100,new RailGeometry.Span("line",20,30)),new RailTollBook.Charge(road,roadOwner,1,100,new RailGeometry.Span("line",40,50))));require(book.totalDebt(payer)==2,"two intervals of the same road aggregate instead of overwriting one debt");
        var restored=new RailTollBook(accounts);restored.load(book.save());require(restored.totalDebt(payer)==2&&restored.save().equals(book.save()),"all debt/receipt state survives round trip");
        UUID train=UUID.randomUUID();var old=restored.passage(train,restored.charges(new RailGeometry.Span("line",0,1)));restored.revise(road,200,true);require(restored.passage(train,restored.charges(new RailGeometry.Span("line",1,2))).getFirst().rate()==100,"ordinary passage locks entry tariff");var tariffRestart=new RailTollBook(accounts);tariffRestart.load(restored.save());require(tariffRestart.passage(train,tariffRestart.charges(new RailGeometry.Span("line",2,3))).getFirst().rate()==100,"entry tariff survives restart");tariffRestart.passage(train,List.of());require(tariffRestart.passage(train,tariffRestart.charges(new RailGeometry.Span("line",0,1))).getFirst().rate()==200,"new entry uses updated tariff");
        var tripAccounts=new Accounts();tripAccounts.balances.put(payer,10L);var trips=new RailTollBook(tripAccounts);trips.register(road,roadOwner,"Rail",100,List.of(new RailGeometry.Span("line",0,100)));var plan=new CompoundTag();plan.putString("Test","return");UUID first=UUID.randomUUID();trips.reserveTrip(first,payer,2,plan);require(tripAccounts.balance(payer)==8,"whole agreed return reserve held before travel");
        var span=new RailGeometry.Span("line",0,5);require(trips.tripTravel(UUID.randomUUID(),first,"APPROACH",0,span,trips.charges(span)),"first partial actual interval accepted");long remaining=trips.trip(first).orElseThrow().getLong("Remaining");require(!trips.tripTravel(UUID.randomUUID(),first,"APPROACH",0,span,trips.charges(span))&&trips.trip(first).orElseThrow().getLong("Remaining")==remaining,"extra loop over consumed interval cannot spend buyer escrow");
        trips.phase(first,"RETURN");require(!trips.tripClosed(first)&&tripAccounts.balance(payer)==8,"delivery phase change cannot prematurely release return funds");require(trips.finishTrip(first)&&trips.trip(first).orElseThrow().getLong("Refunded")==2&&tripAccounts.balance(payer)==10,"unused return reserve refunded exactly and recorded");
        UUID second=UUID.randomUUID();trips.reserveTrip(second,payer,1,plan);require(trips.tripTravel(UUID.randomUUID(),second,"APPROACH",0,span,trips.charges(span))&&tripAccounts.balance(roadOwner)==1,"fractional distance carries across completed trips instead of fee evasion");trips.finishTrip(second);require(tripAccounts.balance(payer)+tripAccounts.balance(roadOwner)==10,"charter toll payment/refund conserves CR");
        var own=trips.charges(new RailGeometry.Span("line",0,100));long before=tripAccounts.balance(roadOwner);trips.travel(UUID.randomUUID(),roadOwner,own);require(tripAccounts.balance(roadOwner)==before&&trips.totalDebt(roadOwner)==0,"self-owned roads do not create fictitious debt or revenue");
        var bad=trips.save();bad.putInt("Version",2);boolean future=false;try{new RailTollBook(tripAccounts).load(bad);}catch(IllegalArgumentException expected){future=true;}require(future,"unknown financial version fails closed");
        var technicalAccounts=new Accounts();var technicalBook=new RailTollBook(technicalAccounts);UUID orphan=UUID.randomUUID();technicalBook.travelUnowned(UUID.randomUUID(),orphan,"Unowned train",List.of(new RailTollBook.Charge(road,roadOwner,1,100,new RailGeometry.Span("line",0,25))));require(technicalBook.technicalDebts().getFirst().assessed()==2&&technicalAccounts.balance(roadOwner)==0,"unowned physical train accrues technical Train UUID debt without issuing CR");var restartedTechnical=new RailTollBook(technicalAccounts);restartedTechnical.load(technicalBook.save());technicalAccounts.balances.put(payer,1L);UUID stableReceipt=restartedTechnical.technicalDebts().getFirst().id();restartedTechnical.resolveTechnical(orphan,payer);require(restartedTechnical.debts().stream().anyMatch(d->d.id().equals(stableReceipt))&&restartedTechnical.totalDebt(payer)==1&&technicalAccounts.balance(roadOwner)==1,"validated owner resolution preserves original receipt and transfers only available cash");restartedTechnical.resolveTechnical(orphan,payer);require(restartedTechnical.totalDebt(payer)==1&&technicalAccounts.balance(roadOwner)==1,"technical owner resolution is idempotent");
        var phaseAccounts=new Accounts();phaseAccounts.balances.put(payer,200L);var commerce=new CargoCommerceBook(phaseAccounts);UUID phaseOrder=UUID.randomUUID();commerce.reserve(phaseOrder,payer,roadOwner,phaseOrder,null,1,100,List.of(new CargoCommerceBook.Fee(road,0,roadOwner,30)));commerce.configureCarrier(phaseOrder,Map.of("APPROACH",10L,"DELIVERY",10L,"RETURN",10L));require(commerce.payCarrierPhase(phaseOrder,"APPROACH")&&commerce.payCarrierPhase(phaseOrder,"APPROACH")&&phaseAccounts.balance(roadOwner)==10,"carrier approach is paid once after its physical proof even before packaging");require(commerce.refundUnattempted(phaseOrder)&&commerce.refunded(phaseOrder)==120&&phaseAccounts.balance(payer)==190,"pre-packaging cancellation refunds only unperformed carrier phases");
        phaseAccounts=new Accounts();phaseAccounts.balances.put(payer,200L);commerce=new CargoCommerceBook(phaseAccounts);phaseOrder=UUID.randomUUID();commerce.reserve(phaseOrder,payer,roadOwner,phaseOrder,null,1,100,List.of(new CargoCommerceBook.Fee(road,0,roadOwner,30)));commerce.configureCarrier(phaseOrder,Map.of("APPROACH",10L,"DELIVERY",10L,"RETURN",10L));commerce.payCarrierPhase(phaseOrder,"APPROACH");commerce.markAttempted(phaseOrder);commerce.requestCancellation(phaseOrder);require(commerce.payCarrierPhase(phaseOrder,"RETURN")&&commerce.settleCancellation(phaseOrder,0,1,h->0)&&commerce.refunded(phaseOrder)==110&&phaseAccounts.balance(roadOwner)==20&&phaseAccounts.balance(payer)==180,"recovered cargo cancellation pays performed approach/return and refunds goods plus unperformed delivery");var phaseRestart=new CargoCommerceBook(phaseAccounts);phaseRestart.load(commerce.save());require(phaseRestart.carrierEarned(phaseOrder)==20&&phaseRestart.refunded(phaseOrder)==110,"phase carrier payments and exact refunds survive restart");
        var metered=new RailTollBook(new Accounts());UUID stream=UUID.randomUUID();var shortCharge=List.of(new RailTollBook.Charge(road,roadOwner,1,100,new RailGeometry.Span("line",0,1)));for(int i=1;i<=1000;i++)metered.meterTravel(stream,i,payer,shortCharge);require(metered.totalDebt(payer)==100&&metered.debts().size()==1&&metered.save().getList("Receipts",11).isEmpty(),"physics observations compact to one debt bucket/high-water stream instead of one permanent UUID per tick");metered.meterTravel(stream,1000,payer,shortCharge);require(metered.totalDebt(payer)==100,"compacted meter stream still rejects replay");
        var pendingAccounts=new Accounts();pendingAccounts.balances.put(payer,30L);pendingAccounts.blocked.add(roadOwner);var pendingBook=new RailTollBook(pendingAccounts);pendingBook.register(road,roadOwner,"Pending",1000,List.of(new RailGeometry.Span("line",0,20)));var nodeA=new RailRoutes.Node("minecraft:overworld",0,0,0);var nodeB=new RailRoutes.Node("minecraft:overworld",20,0,0);var returnPath=new RailRoutes.Path(UUID.randomUUID(),false,List.of(new RailRoutes.Segment(nodeA,nodeB,0,20,new RailGeometry.Span("line",0,20))),20);var pendingPlan=new CompoundTag();var pendingPhases=new CompoundTag();var pendingPhase=new CompoundTag();pendingPhase.put("Path",returnPath.save());pendingPhase.put("MeterPath",returnPath.save());pendingPhases.put("RETURN",pendingPhase);pendingPlan.put("Phases",pendingPhases);UUID pendingOrder=UUID.randomUUID();pendingBook.reserveTrip(pendingOrder,payer,25,pendingPlan);pendingBook.phase(pendingOrder,"RETURN");require(!pendingBook.phaseComplete(pendingOrder,"RETURN"),"station arrival alone is not proof of billed physical phase");for(int i=0;i<20;i++){var actual=new RailGeometry.Span("line",i,i+1);require(pendingBook.tripTravel(UUID.randomUUID(),pendingOrder,"RETURN",0,actual,pendingBook.charges(actual)),"creditor overflow retains actual movement proof and funded payable");}require(!pendingBook.phaseComplete(pendingOrder,"RETURN"),"fixed toll meter alone is not navigation-head completion evidence");for(int i=0;i<20;i++)require(pendingBook.headTravel(pendingOrder,"RETURN",0,new RailGeometry.Span("line",i,i+1)),"independent actual navigation head coverage");require(pendingBook.phaseComplete(pendingOrder,"RETURN")&&pendingBook.trip(pendingOrder).orElseThrow().getList("Payables",10).size()==1&&pendingAccounts.balance(roadOwner)==0&&!pendingBook.finishTrip(pendingOrder),"pending creditor payout coalesces while preserving physical completion and held funds");pendingAccounts.blocked.clear();require(pendingBook.finishTrip(pendingOrder)&&pendingAccounts.balance(roadOwner)==20&&pendingAccounts.balance(payer)==10,"funded pending payout/remainder refund complete without replaying movement");
        UUID oldShipment=UUID.randomUUID();var fleetSave=new CompoundTag();fleetSave.putInt("Version",1);var terminal=new ListTag();terminal.add(NbtUtils.createUUID(oldShipment));fleetSave.put("Completed",terminal);var fleet=PublicFleetRegistry.load(fleetSave,null);var newJobs=new ListTag();var newJob=new CompoundTag();newJob.putUUID("Train",UUID.randomUUID());newJob.putUUID("Shipment",UUID.randomUUID());newJob.putString("Phase","DONE");newJobs.add(newJob);var reused=fleet.save(new CompoundTag(),null);reused.put("Jobs",newJobs);require(PublicFleetRegistry.load(reused,null).complete(oldShipment),"physical terminal receipt survives restart and reuse/overwrite of a train job");
        var overlapAccounts=new Accounts();var prefixBook=new RailTollBook(overlapAccounts);UUID prefixOrder=UUID.randomUUID();prefixBook.reserveTrip(prefixOrder,payer,0,pendingPlan);prefixBook.phase(prefixOrder,"RETURN");require(prefixBook.headTravel(prefixOrder,"RETURN",0,new RailGeometry.Span("line",0,10)),"head prefix before restart");var prefixRestart=new RailTollBook(overlapAccounts);prefixRestart.load(prefixBook.save());require(prefixRestart.headTravel(prefixOrder,"RETURN",0,new RailGeometry.Span("line",9.5,10.5))&&prefixRestart.headTravel(prefixOrder,"RETURN",0,new RailGeometry.Span("line",10.5,20))&&prefixRestart.phaseComplete(prefixOrder,"RETURN"),"mixed covered/unseen restart interval clips prefix without leaving an unrecoverable head-proof gap");require(prefixRestart.tripTravel(UUID.randomUUID(),prefixOrder,"RETURN",0,new RailGeometry.Span("line",0,10),List.of())&&prefixRestart.tripTravel(UUID.randomUUID(),prefixOrder,"RETURN",0,new RailGeometry.Span("line",9.5,10.5),List.of())&&prefixRestart.tripTravel(UUID.randomUUID(),prefixOrder,"RETURN",0,new RailGeometry.Span("line",10.5,20),List.of()),"toll coverage clips replayed prefix while accepting exactly contiguous new distance");
        var zeroReturnAccounts=new Accounts();zeroReturnAccounts.balances.put(payer,200L);var zeroReturn=new CargoCommerceBook(zeroReturnAccounts);UUID cancelledHome=UUID.randomUUID();zeroReturn.reserve(cancelledHome,payer,roadOwner,cancelledHome,null,1,100,List.of(new CargoCommerceBook.Fee(road,0,roadOwner,30)));zeroReturn.configureCarrier(cancelledHome,Map.of("APPROACH",10L,"DELIVERY",10L,"RETURN",10L));zeroReturn.payCarrierPhase(cancelledHome,"APPROACH");zeroReturn.markAttempted(cancelledHome);zeroReturn.requestCancellation(cancelledHome);require(zeroReturn.payCarrierPhase(cancelledHome,"RETURN",0)&&zeroReturn.settleCancellation(cancelledHome,0,1,h->0)&&zeroReturn.refunded(cancelledHome)==120&&zeroReturnAccounts.balance(roadOwner)==10,"cancelled train already home cannot earn an unperformed return fare");var zeroReload=new CargoCommerceBook(zeroReturnAccounts);zeroReload.load(zeroReturn.save());require(zeroReload.carrierEarned(cancelledHome)==10,"actual capped/zero phase earnings survive restart");
        System.out.println("PASS: "+checks+" rail debt, claim, tariff, trip replay and return-reserve checks");
    }
}
